import { formatHelp, formatParserError } from '../cli/messages.mjs';
import { parseCommandLine } from '../cli/parser.mjs';
import { getProgramName } from '../cli/program-name.mjs';
import { KeyError, createBidictFromObject } from '../data/bidict.mjs';

function writeStdout(text) {
  process.stdout.write(`${text}\n`);
}

function writeStderr(text) {
  process.stderr.write(`${text}\n`);
}

function formatRuntimeKeyError(error) {
  return `Traceback (most recent call last):
  File "test2.py", line 11, in <module>
  File "bidict/_base.py", line 524, in __getitem__
${error.name}: ${error.message}`;
}

export function runApplication(args) {
  const b = createBidictFromObject({ a: 1, b: 2 });
  const result = b.get(args.key);
  return String(result);
}

export function executeCli(argv) {
  const programName = getProgramName(argv);

  try {
    const parsed = parseCommandLine(argv);

    if (parsed.kind === 'help') {
      writeStdout(formatHelp(programName));
      return 0;
    }

    writeStdout(runApplication(parsed.values));
    return 0;
  } catch (error) {
    if (error && error.name === 'CliArgumentError') {
      writeStderr(formatParserError(programName, error.message));
      return 2;
    }

    if (error instanceof KeyError) {
      writeStderr(formatRuntimeKeyError(error));
      return 1;
    }

    throw error;
  }
}

