function formatPythonString(value) {
  return `'${String(value).replace(/\\/g, '\\\\').replace(/'/g, "\\'")}'`;
}

export class KeyError extends Error {
  constructor(key) {
    super(formatPythonString(key));
    this.name = 'KeyError';
    this.key = key;
  }
}

export class Bidict {
  constructor(initialEntries = []) {
    this.forward = Object.create(null);
    this.inverse = Object.create(null);

    for (const [key, value] of initialEntries) {
      this.set(key, value);
    }
  }

  set(key, value) {
    const keyText = String(key);
    const valueText = String(value);

    if (Object.prototype.hasOwnProperty.call(this.forward, keyText)) {
      const previousValue = this.forward[keyText];
      delete this.inverse[String(previousValue)];
    }

    if (Object.prototype.hasOwnProperty.call(this.inverse, valueText)) {
      const previousKey = this.inverse[valueText];
      delete this.forward[previousKey];
    }

    this.forward[keyText] = value;
    this.inverse[valueText] = keyText;
    return this;
  }

  get(key) {
    const keyText = String(key);

    if (!Object.prototype.hasOwnProperty.call(this.forward, keyText)) {
      throw new KeyError(keyText);
    }

    return this.forward[keyText];
  }
}

export function createBidictFromObject(source) {
  const entries = [];

  for (const key of Object.keys(source)) {
    entries.push([key, source[key]]);
  }

  return new Bidict(entries);
}

