function createCliArgumentError(message) {
  const error = new Error(message);
  error.name = 'CliArgumentError';
  return error;
}

function resolveLongOption(rawName) {
  const matches = LONG_OPTION_NAMES.filter((optionName) => optionName.startsWith(rawName));
  return matches.length === 1 ? matches[0] : null;
}

function splitLongToken(token) {
  const optionBody = token.slice(2);
  const separatorIndex = optionBody.indexOf('=');

  if (separatorIndex === -1) {
    return { optionName: optionBody, inlineValue: null };
  }

  return {
    optionName: optionBody.slice(0, separatorIndex),
    inlineValue: optionBody.slice(separatorIndex + 1),
  };
}

function isMissingOptionValue(nextToken) {
  return nextToken === undefined || nextToken.startsWith('-');
}

export function parseCommandLine(argv) {
  const tokens = Array.isArray(argv) ? argv.slice(2) : [];
  const parsedValues = {};
  const extras = [];

  for (let index = 0; index < tokens.length; index += 1) {
    const token = tokens[index];

    if (token.startsWith('--')) {
      if (token === '--') {
        extras.push(token);
        continue;
      }

      const { optionName, inlineValue } = splitLongToken(token);
      const resolvedOption = resolveLongOption(optionName);

      if (resolvedOption === null) {
        extras.push(token);
        continue;
      }

      if (resolvedOption === 'help') {
        if (inlineValue !== null) {
          throw createCliArgumentError(
            `argument -h/--help: ignored explicit argument '${inlineValue}'`,
          );
        }

        return { kind: 'help' };
      }

      if (inlineValue !== null) {
        parsedValues[resolvedOption] = inlineValue;
        continue;
      }

      const nextToken = tokens[index + 1];
      if (isMissingOptionValue(nextToken)) {
        throw createCliArgumentError(`argument --${resolvedOption}: expected one argument`);
      }

      parsedValues[resolvedOption] = nextToken;
      index += 1;
      continue;
    }

    if (token.startsWith('-')) {
      if (token.startsWith('-h')) {
        if (token.startsWith('-h=')) {
          throw createCliArgumentError(
            `argument -h/--help: ignored explicit argument '${token.slice(3)}'`,
          );
        }

        return { kind: 'help' };
      }

      extras.push(token);
      continue;
    }

    extras.push(token);
  }

  const missing = [];
  if (!Object.prototype.hasOwnProperty.call(parsedValues, 'key')) {
    missing.push('--key');
  }
  if (!Object.prototype.hasOwnProperty.call(parsedValues, 'val')) {
    missing.push('--val');
  }
